<?php
declare(strict_types=1);
namespace App\Interface\Http\QuestionLearning\Controller;
use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Application\QuestionLearning\DTO\Request\CreateQuestionCommentRequestDto;use App\Application\QuestionLearning\DTO\Request\CreateQuestionProblemReportRequestDto;use App\Application\QuestionLearning\DTO\Request\SaveQuestionNoteRequestDto;use App\Application\QuestionLearning\DTO\Request\UpdateQuestionInteractionRequestDto;use App\Application\QuestionLearning\Service\CreateQuestionCommentService;use App\Application\QuestionLearning\Service\CreateQuestionProblemReportService;use App\Application\QuestionLearning\Service\GetQuestionInteractionService;use App\Application\QuestionLearning\Service\GetQuestionNoteService;use App\Application\QuestionLearning\Service\ListQuestionCommentsService;use App\Application\QuestionLearning\Service\SaveQuestionNoteService;use App\Application\QuestionLearning\Service\UpdateQuestionInteractionService;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class QuestionLearningController { public function __construct(private readonly AuthService $auth,private readonly GetQuestionInteractionService $getInteraction,private readonly UpdateQuestionInteractionService $updateInteraction,private readonly GetQuestionNoteService $getNote,private readonly SaveQuestionNoteService $saveNote,private readonly ListQuestionCommentsService $comments,private readonly CreateQuestionCommentService $createComment,private readonly CreateQuestionProblemReportService $reports,private readonly ApiResponseFactory $responses) {} public function getInteraction(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, string $questionId): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->getInteraction->execute($userId,$questionId)); } public function updateInteraction(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, UpdateQuestionInteractionRequestDto $input): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->updateInteraction->execute($userId,$input,new \DateTimeImmutable())); } public function getNote(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, string $questionId): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->getNote->execute($userId,$questionId)); } public function saveNote(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, SaveQuestionNoteRequestDto $input): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->saveNote->execute($userId,$input,new \DateTimeImmutable())); } public function listComments(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, string $questionId, int $page, int $perPage): ResponseInterface { try { $user=$this->auth->currentUser($access); $result=$this->comments->execute($questionId,$page,$perPage); return $this->responses->paginated($response,$result['items'],(string)$request->getAttribute('request_id'),$result['page'],$result['perPage'],$result['total']); } catch (\Throwable $error) { return $this->problem($request,$response,$error); } } public function createComment(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, CreateQuestionCommentRequestDto $input): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->createComment->execute($userId,$input,new \DateTimeImmutable())); } public function createReport(ServerRequestInterface $request, ResponseInterface $response, AccessTokenRequestDto $access, CreateQuestionProblemReportRequestDto $input): ResponseInterface { return $this->run($request,$response,$access,fn(string $userId) => $this->reports->execute($userId,$input,new \DateTimeImmutable())); } private function run(ServerRequestInterface $request,ResponseInterface $response,AccessTokenRequestDto $access,callable $operation): ResponseInterface { try { $user=$this->auth->currentUser($access);return $this->responses->success($response,$operation($user->id),(string)$request->getAttribute('request_id')); } catch (\Throwable $error) { return $this->problem($request,$response,$error); } } private function problem(ServerRequestInterface $request,ResponseInterface $response,\Throwable $error): ResponseInterface { $requestId=(string)$request->getAttribute('request_id'); if ($error instanceof \InvalidArgumentException) return $this->responses->problem($response,'VALIDATION_FAILED','Um ou mais campos são inválidos.',422,$requestId); if ($error instanceof \DomainException && str_contains($error->getMessage(),'não encontrada')) return $this->responses->problem($response,'RESOURCE_NOT_FOUND','Recurso não encontrado.',404,$requestId); return $this->responses->problem($response,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,$requestId); } }
